137	HcclResult GetHcclDfxOpInfoDataCount(const OpParam& param, const u32& rankSize, uint64_t& sendCount)
138	{
139	    sendCount = 0;
140	    if (param.opType == HcclCMDType::HCCL_CMD_ALLTOALL) {
141	        CHK_PTR_NULL(param.all2AllVDataDes.sendCounts);
142	        sendCount
143	            += *(reinterpret_cast<const uint64_t*>(param.all2AllVDataDes.sendCounts)); // 非v类算子，只上报入参里的count
144	    } else if (param.opType == HcclCMDType::HCCL_CMD_ALLTOALLV || param.opType == HcclCMDType::HCCL_CMD_ALLTOALLVC) {
145	        CHK_PTR_NULL(param.all2AllVDataDes.sendCounts);
146	        for (u64 i = 0; i < rankSize; i++) { // v类算子上报累加的count
147	            sendCount += *(reinterpret_cast<const uint64_t*>(param.all2AllVDataDes.sendCounts) + i);
148	        }
149	    } else if (param.opType == HcclCMDType::HCCL_CMD_ALLGATHER_V) {
150	        CHK_PTR_NULL(param.varData);
151	        for (u64 i = 0; i < rankSize; i++) {
152	            sendCount += *(reinterpret_cast<const uint64_t*>(param.varData) + i);
153	        }
154	    } else if (param.opType == HcclCMDType::HCCL_CMD_REDUCE_SCATTER_V) {
155	        CHK_PTR_NULL(param.varData);
156	        for (u64 i = rankSize; i < 2 * rankSize; i++) {
157	            sendCount += *(reinterpret_cast<const uint64_t*>(param.varData) + i);
158	        }
159	    } else if (param.opType == HcclCMDType::HCCL_CMD_BATCH_SEND_RECV) {
160	        CHK_PRT_RET(
161	            param.batchSendRecvDataDes.sendRecvItemsPtr == nullptr,
162	            HCCL_ERROR(
163	                "[%s]fail, tag[%s] sendRecvItemsPtr is nullptr, itemNum[%u]", __func__, param.tag,
164	                param.batchSendRecvDataDes.itemNum),
165	            HCCL_E_PTR);
166	        for (u32 idx = 0; idx < param.batchSendRecvDataDes.itemNum; idx++) {
167	            HcclSendRecvItem* item = param.batchSendRecvDataDes.sendRecvItemsPtr + idx;
168	            sendCount += item->count;
169	        }
170	    } else {
171	        sendCount = param.DataDes.count;
172	    }
173	    HCCL_INFO(
174	        "[%s]tag[%s], sendCount[%u], opType[%u], rankSize[%u]", __func__, param.tag, sendCount, param.opType, rankSize);
175	    return HCCL_SUCCESS;
176	}
