203	HcclResult AppendFastLaunchTag(
204	    OpParam& param, const char* dataTypeStr, const char* reduceOpStr, const char* countStr, const char* rootStr)
205	{
206	    char* dst = param.fastLaunchTag;
207	    size_t remain = sizeof(param.fastLaunchTag);
208	
209	    auto append_str = [&](const char* s) -> bool {
210	        if (!s)
211	            return true;
212	        size_t len = strlen(s);
213	        if (len >= remain)
214	            return false;
215	        if (memcpy_s(dst, remain, s, len) != EOK) {
216	            HCCL_ERROR("memcpy_s failed in append_str.");
217	            return false;
218	        }
219	        dst += len;
220	        remain -= len;
221	        return true;
222	    };
223	    if (!append_str(param.tag) || !append_str("_") || !append_str(dataTypeStr)) {
224	        goto fail;
225	    }
226	    if (reduceOpStr && (!append_str("_") || !append_str(reduceOpStr))) {
227	        goto fail;
228	    }
229	    if (countStr && (!append_str("_") || !append_str(countStr))) {
230	        goto fail;
231	    }
232	    if (rootStr && (!append_str("_r") || !append_str(rootStr))) {
233	        goto fail;
234	    }
235	    *dst = '\0';
236	    HCCL_INFO("[SetOpParamFastLaunchTag] fastLaunchTag: [%s]", param.fastLaunchTag);
237	    return HcclResult::HCCL_SUCCESS;
238	
239	fail:
240	    HCCL_ERROR("failed to fill fastLaunchTag");
241	    return HcclResult::HCCL_E_INTERNAL;
242	}
