244	HcclResult SetOpParamFastLaunchTag(OpParam& param)
245	{
246	    // 1. 数据类型
247	    const char* dataTypeStr = nullptr;
248	    if (param.opType == HcclCMDType::HCCL_CMD_ALLTOALL || param.opType == HcclCMDType::HCCL_CMD_ALLTOALLV
249	        || param.opType == HcclCMDType::HCCL_CMD_ALLTOALLVC) {
250	        dataTypeStr = GetHcclDataTypeStr(param.all2AllVDataDes.sendType);
251	    } else {
252	        dataTypeStr = GetHcclDataTypeStr(param.DataDes.dataType);
253	    }
254	    CHK_PRT_RET((!dataTypeStr), HCCL_ERROR("unsupported data type"), HcclResult::HCCL_E_INTERNAL);
255	    // 2. reduce op
256	    const char* reduceOpStr = nullptr;
257	    if (param.opType == HcclCMDType::HCCL_CMD_ALLREDUCE || param.opType == HcclCMDType::HCCL_CMD_REDUCE_SCATTER
258	        || param.opType == HcclCMDType::HCCL_CMD_REDUCE || param.opType == HcclCMDType::HCCL_CMD_REDUCE_SCATTER_V) {
259	        reduceOpStr = GetHcclReduceOpStr(param.reduceType);
260	        CHK_PRT_RET((!reduceOpStr), HCCL_ERROR("unsupported reduce op"), HcclResult::HCCL_E_INTERNAL);
261	    }
262	    // 3. count
263	    char countBuf[32];
264	    const char* countStr = nullptr;
265	    if (param.opType != HcclCMDType::HCCL_CMD_ALLTOALLV) {
266	        u64 count = (param.opType == HcclCMDType::HCCL_CMD_ALLTOALL) ?
267	                        *reinterpret_cast<u64*>(param.all2AllVDataDes.sendCounts) :
268	                        param.DataDes.count;
269	        int countLen = snprintf_s(countBuf, sizeof(countBuf), sizeof(countBuf) - 1, "%llu", count);
270	        CHK_PRT_RET((countLen <= 0), HCCL_ERROR("failed to format count"), HcclResult::HCCL_E_INTERNAL);
271	        countStr = countBuf;
272	    }
273	    // 4. root
274	    char rootBuf[10];
275	    const char* rootStr = nullptr;
276	    if (param.opType == HcclCMDType::HCCL_CMD_REDUCE || param.opType == HcclCMDType::HCCL_CMD_SCATTER
277	        || param.opType == HcclCMDType::HCCL_CMD_BROADCAST) {
278	        int rootLen
279	            = snprintf_s(rootBuf, sizeof(rootBuf), sizeof(rootBuf) - 1, "%llu", static_cast<uint64_t>(param.root));
280	        CHK_PRT_RET((rootLen <= 0), HCCL_ERROR("failed to format root"), HcclResult::HCCL_E_INTERNAL);
281	        rootStr = rootBuf;
282	    }
283	    // 5 一次性拼接
284	    return AppendFastLaunchTag(param, dataTypeStr, reduceOpStr, countStr, rootStr);
285	}
