311	        *ccuFastLaunchCtx = reinterpret_cast<CcuFastLaunchCtx*>(fastLaunchCtxPtr);
312	        return true;
313	    }
314	    return false;
315	#else
316	    (void)comm;
317	    (void)param;
318	    (void)ccuFastLaunchCtx;
319	    return false;
