460	HcclResult HcclExecOpCcuFastLaunch(HcclComm comm, OpParam& param, const CcuFastLaunchCtx* ccuFastLaunchCtx)
461	{
462	#if CANN_VERSION_NUM >= CANN_VERSION(9, 1, 0)
463	    HCCL_INFO("[HcclExecOpCcuFastLaunch] HcclExecOpCcuFastLaunch start");
464	    std::string algName = ccuFastLaunchCtx->algName;
465	    HCCL_DEBUG("[HcclExecOpCcuFastLaunch] algName: [%s]", algName.c_str());
466	    std::unique_ptr<InsCollAlgBase> executor = CollAlgExecRegistryV2::Instance().GetAlgExec(param.opType, algName);
467	    CHK_PRT_RET(
468	        executor.get() == nullptr, HCCL_ERROR("Fail to find executor for algName[%s]", algName.c_str()), HCCL_E_PARA);
469	
470	    void* cclBufferAddr;
471	    uint64_t cclBufferSize;
472	    // 从通信域获取CCL buffer
473	    CHK_RET(HcclGetHcclBuffer(comm, &cclBufferAddr, &cclBufferSize));
474	    // CCL IN使用所有的CCL Buffer，这个其实就是scratch buffer
475	    param.hcclBuff = HcclMem{HCCL_MEM_TYPE_DEVICE, cclBufferAddr, cclBufferSize};
476	    // 覆盖主流
477	    ThreadHandle mainThread;
478	    CHK_RET(HcclThreadAcquireWithStream(
479	        comm, param.engine, param.stream, ccuFastLaunchCtx->notifyNumOnMainThread, &mainThread));
480	    ThreadHandle* threads = ccuFastLaunchCtx->GetThreadHandlePtr();
481	    threads[0] = mainThread;
482	    std::vector<ThreadHandle> threadTemps;
483	    threadTemps.assign(threads, threads + ccuFastLaunchCtx->threadNum);
484	    uint64_t beginTime = HcommGetProfilingSysCycleTime();
485	    // Op注册
486	    HcclDfxOpInfoCompat hcclDfxOpInfo{};
487	    CHK_RET(ConstructHcclDfxOpInfo(param, param.fastLaunchTag, ALG_TAG_LENGTH, hcclDfxOpInfo, 0));
488	    param.dataCount = hcclDfxOpInfo.dataCount;
489	    CHK_RET(HcclDfxRegOpInfoByCommId(param.commName, reinterpret_cast<void*>(&hcclDfxOpInfo)));
490	    if (IsStreamInCaptureMode(param.stream) && threadTemps.size() > 1) {
491	        HCCL_INFO("HcclExecOpCcuFastLaunch streamnum %d add slavestream", threadTemps.size());
492	        CHK_RET(CaptureSlaveStreams(comm, param.stream, threadTemps, param.isCapture));
493	    }
494	
495	    HCCL_INFO("[HcclExecOpCcuFastLaunch] FastLaunch start");
496	    CHK_RET(executor->FastLaunch(param, ccuFastLaunchCtx));
497	    CHK_RET(HcclProfilingReportOp(comm, beginTime));
498	    HCCL_INFO("[HcclExecOpCcuFastLaunch] HcclExecOpCcuFastLaunch end");
499	    return HCCL_SUCCESS;
500	#else
501	    (void)comm;
502	    (void)param;
503	    (void)ccuFastLaunchCtx;
504	    return HCCL_E_NOT_SUPPORT;
505	#endif
506	}
