508	HcclResult ExecuteAivCacheLogic(
509	    HcclComm comm, OpParam& param, const std::string& algName, std::unique_ptr<InsCollAlgBase>& executor,
510	    AlgResourceCtxSerializable& resCtxHost)
511	{
512	    bool useCache = IsAivCacheSupported(param);
513	
514	    std::string ctxTag;
515	    u64 keyHash = 0;
516	    if (useCache) {
517	        AivOpCacheArgs cacheKey = {};
518	        cacheKey.root = param.root;
519	        cacheKey.commName = param.commName;
520	        cacheKey.opType = param.opType;
521	        cacheKey.reduceOp = param.reduceType;
522	        cacheKey.numBlocksLimit = param.numBlocksLimit;
523	        if (param.opType == HCCL_CMD_ALLTOALL) {
524	            cacheKey.dataType = param.all2AllVDataDes.sendType;
525	            cacheKey.count = static_cast<const u64*>(param.all2AllVDataDes.sendCounts)[0];
526	        } else if (param.opType == HCCL_CMD_ALLTOALLV) {
527	            cacheKey.dataType = param.all2AllVDataDes.sendType;
528	            cacheKey.count = 0; // counts 在 replay 时动态刷新,cache key 不区分
529	        } else {
530	            cacheKey.count = param.DataDes.count;
531	            cacheKey.dataType = param.DataDes.dataType;
532	        }
533	        keyHash = CalcAivCacheKeyHash(cacheKey);
534	        CHK_RET(BuildAivCacheCtxTag(keyHash, ctxTag));
535	        g_recordingQueue = std::make_shared<InsQueue>();
536	        g_baseInputAddr = reinterpret_cast<u64>(param.inputPtr);
537	        g_baseOutputAddr = reinterpret_cast<u64>(param.outputPtr);
538	    }
539	
540	    CHK_RET(executor->Orchestrate(param, resCtxHost));
541	
542	    if (useCache && g_recordingQueue) {
543	        AivCacheIndexCtx* indexCtx = nullptr;
544	        CHK_RET(GetOrCreateAivCacheIndexCtx(comm, &indexCtx));
545	        CHK_RET(EvictAivCacheIfNeeded(comm, indexCtx));
546	        CHK_RET(StoreAivCacheCtx(comm, ctxTag, keyHash, algName, indexCtx));
547	        g_recordingQueue = nullptr;
548	        g_baseInputAddr = 0;
549	        g_baseOutputAddr = 0;
550	    }
551	    return HCCL_SUCCESS;
552	}
