572	HcclResult
573	ReSelector(HcclComm comm, OpParam& param, std::unique_ptr<TopoInfoWithNetLayerDetails>& topoInfo, std::string& algName)
574	{
575	    (void)comm;
576	    HCCL_INFO("Start to execute ReSelector.");
577	    // 回退AICPU
578	    param.opExecuteConfig = OpExecuteConfig::AICPU_TS;
579	    // 拓扑已有，无需再计算
580	
581	    // 算法选择，选择完后顺便param.algTag设置了，资源的保存是以算子+算法为单位
582	    std::shared_ptr<ExecuteSelector> collAlgSelector = std::make_shared<ExecuteSelector>(ExecuteSelector());
583	    CHK_RET(collAlgSelector->Run(param, topoInfo.get(), algName));
584	    if (algName == "") {
585	        HCCL_ERROR("[ReSelector] select algname fail!");
586	        return HCCL_E_PTR;
587	    }
588	    CHK_RET(SetCommEngine(param));
589	    // AIV_ONLY 模式下禁止回退到非 AIV 引擎，未选中 AIV 时直接返回不支持。
590	    if (param.commOpExpansionMode == HcclOpExpansionMode::HCCL_OP_EXPANSION_AIV_ONLY
591	        && param.engine != CommEngine::COMM_ENGINE_AIV) {
592	        HCCL_ERROR(
593	            "[HcclExecOp] opType[%d] currently do not select aiv mode, aiv only not support.",
594	            static_cast<int>(param.opType));
595	        return HCCL_E_NOT_SUPPORT;
596	    }
597	    // 如果一开始读取到的Engine不是aicpu，经过算法选择后回退到aicpu，则需要重新LoadAICPUKernel
598	    if ((param.engine == CommEngine::COMM_ENGINE_AICPU_TS) || (param.engine == CommEngine::COMM_ENGINE_CPU)) {
599	        HCCL_DEBUG("[ReSelector] is aicpu mode");
600	        CHK_RET(LoadAICPUKernel()); // 该函数内部有防止重复加载的逻辑
601	    }
602	    CHK_RET(SetOpParamAlgTag(param, algName));
603	    HCCL_INFO("Success to execute ReSelector.");
604	    return HCCL_SUCCESS;
605	}
