1097	HcclResult HcclCalcTopoInfo(HcclComm comm, OpParam& param, std::unique_ptr<TopoInfoWithNetLayerDetails>& topoInfo)
1098	{
1099	    HCCL_INFO("[%s] HcclCalcTopoInfo start.", __func__);
1100	    uint64_t size = 0;
1101	    void* ctx = nullptr;
1102	    // 若获取Context失败，表示对应Context尚未缓存
1103	    HcclResult ret = HcclEngineCtxGet(comm, param.tag, CommEngine::COMM_ENGINE_CPU_TS, &ctx, &size);
1104	    if (ret == HCCL_E_NOT_FOUND || ret == HCCL_E_PARA) {
1105	        // 初始化topoInfo
1106	        CHK_RET(InitRankInfo(comm, topoInfo.get()));
1107	        // 序列化
1108	        std::vector<char> seq = topoInfo->Serialize();
1109	        size = seq.size();
1110	        // 创建新的Context保存
1111	        CHK_RET(HcclEngineCtxCreate(comm, param.tag, CommEngine::COMM_ENGINE_CPU_TS, size, &ctx));
1112	        CHK_SAFETY_FUNC_RET(memcpy_s(ctx, size, seq.data(), size));
1113	        return HCCL_SUCCESS;
1114	    }
1115	    char* ctxTemp = reinterpret_cast<char*>(ctx);
1116	    std::vector<char> seq(ctxTemp, ctxTemp + size);
1117	    TopoInfoWithNetLayerDetails topoInfoTemp;
1118	    topoInfoTemp.DeSerialize(seq);
1119	    topoInfo = std::make_unique<TopoInfoWithNetLayerDetails>(std::move(topoInfoTemp));
1120	    HCCL_INFO("[%s] HcclCalcTopoInfo end.", __func__);
1121	    return HCCL_SUCCESS;
1122	}
