1143	static HcclResult TryReuseResource(
1144	    HcclComm comm, OpParam& param, bool& increCreateChannelFlag, void** resCtxSequence, uint64_t& size,
1145	    bool& isResourceReused)
1146	{
1147	    // 增量建链模式下不能复用资源
1148	    if (param.opType == HcclCMDType::HCCL_CMD_BATCH_SEND_RECV && param.opMode == OpMode::OPBASE) {
1149	        increCreateChannelFlag = true;
1150	        return HCCL_E_NOT_FOUND;
1151	    }
1152	    // 非OPBASE模式且非CCU引擎不能复用资源
1153	    if (param.opMode != OpMode::OPBASE && param.engine != CommEngine::COMM_ENGINE_CCU) {
1154	        return HCCL_E_NOT_FOUND;
1155	    }
1156	    void* ctx = nullptr;
1157	    // 这种情况下资源已经有了
1158	    CommEngine ctxEngine = param.engine;
1159	    if (param.engine == CommEngine::COMM_ENGINE_AIV) {
1160	        // AIV模式固定利用利用algTag申请1块host内存resCtx
1161	        ctxEngine = COMM_ENGINE_CPU_TS;
1162	    } else if (param.engine == COMM_ENGINE_CPU) {
1163	        // host dpu申请device内存用于存放resctx
1164	        ctxEngine = COMM_ENGINE_AICPU_TS;
1165	    }
1166	    if (HcclEngineCtxGet(comm, param.algTag, ctxEngine, &ctx, &size) == HCCL_SUCCESS) {
1167	        HCCL_DEBUG("Already have context, skip create, ctxSize is %llu", size);
1168	        isResourceReused = true;
1169	        *resCtxSequence = ctx;
1170	        param.ctxSize = size;
1171	        return HCCL_SUCCESS;
1172	    }
1173	    return HCCL_E_NOT_FOUND;
1174	}
