1176	HcclResult HcclGetAlgRes(
1177	    HcclComm comm, OpParam& param, std::unique_ptr<InsCollAlgBase>& executor, TopoInfoWithNetLayerDetails* topoInfo,
1178	    std::unique_ptr<AlgResourceCtxSerializable>& resCtxHost, void** resCtxSequence, bool& isResourceReused,
1179	    const ResPackGraphMode& resPack)
1180	{
1181	    HCCL_INFO("[HcclGetAlgRes] Start to execute HcclGetAlgRes.");
1182	
1183	    bool increCreateChannelFlag = false;
1184	    uint64_t size = 0;
1185	    if (TryReuseResource(comm, param, increCreateChannelFlag, resCtxSequence, size, isResourceReused) == HCCL_SUCCESS) {
1186	        return HCCL_SUCCESS;
1187	    }
1188	
1189	    // context创建前做是否需要参数一致性的判断，context未创建则判断为首次下发该算子
1190	    needInconsistentCheck = NeedInconsistentCheck(comm, param);
1191	
1192	    // 计算AlgHierarchyInfo
1193	    AlgHierarchyInfoForAllLevel algHierarchyInfo; // 分级通信域信息{localRankId, localRankSize}
1194	    CHK_RET(executor->CalcAlgHierarchyInfo(comm, topoInfo, algHierarchyInfo));
1195	    // 资源计算
1196	    HCCL_INFO("[HcclGetAlgRes] executor->CalcRes.");
1197	    AlgResourceRequest resRequest;
1198	    CHK_RET(executor->CalcRes(comm, param, topoInfo, algHierarchyInfo, resRequest));
1199	    auto ret = GetAlgResWithEngine(
1200	        comm, param, resRequest, resCtxHost, topoInfo, algHierarchyInfo, resCtxSequence, size, increCreateChannelFlag,
1201	        resPack);
1202	    if (ret == HCCL_E_UNAVAIL) {
1203	        return HCCL_E_UNAVAIL;
1204	    }
1205	    CHK_RET(ret);
1206	
1207	    if (resCtxHost != nullptr) {
1208	        // 拼接各level的channel数量信息
1209	        std::string channelNumInfo;
1210	        for (size_t i = 0; i < resCtxHost->channels.size(); i++) {
1211	            if (i > 0)
1212	                channelNumInfo += ", ";
1213	            channelNumInfo += "level" + std::to_string(i) + "[" + std::to_string(resCtxHost->channels[i].size()) + "]";
1214	        }
1215	        HCCL_RUN_INFO(
1216	            "[HcclGetAlgRes] engine[%s], algTag[%s], resource allocated: thread num[%u], "
1217	            "channel num per level[%s], ccu kernel num[%u].",
1218	            GetEnumToString(GetCommEngineStatusStrMap(), param.engine).c_str(), param.algTag,
1219	            resCtxHost->threads.size(), channelNumInfo.c_str(), resCtxHost->ccuKernels.size());
1220	    }
1221	
1222	    // 参数一致性校验
1223	    if (needInconsistentCheck) {
1224	        OpExchangeInfo exchangeInfo{};
1225	        CHK_RET(FillOpExchangeInfo(comm, param, exchangeInfo));
1226	        CHK_RET(CompareOpExchangeInfos(comm, param, resRequest, exchangeInfo));
1227	    }
1228	
1229	    return HCCL_SUCCESS;
1230	}
