1236	    CHK_RET(HcclGetHcclBuffer(comm, &cclBufferAddr, &exchangeInfo.cclBufferSize));
1237	    exchangeInfo.root = param.root;
1238	    exchangeInfo.opType = param.opType;
1239	    exchangeInfo.opExecuteConfig = param.opExecuteConfig;
1240	    exchangeInfo.reduceType = param.reduceType;
1241	    CHK_RET(FillOpExchangeInfoWithDataDes(param, exchangeInfo));
1242	
1243	    u32 numBlocksLimit = 0;
1244	    AivParamStorage* aivParam = nullptr;
1245	    HcclResult ret = GetAivParamStorageByComm(comm, &aivParam, false);
1246	    if (ret == HCCL_SUCCESS && aivParam != nullptr) {
1247	        numBlocksLimit = aivParam->aivCoreLimit;
1248	        exchangeInfo.aivCoreLimit = numBlocksLimit;
1249	    }
1250	    if (numBlocksLimit == 0 && param.opMode == OpMode::OPBASE) {
1251	        ACLCHECK(aclrtGetResInCurrentThread(ACL_RT_DEV_RES_VECTOR_CORE, &numBlocksLimit));
1252	        exchangeInfo.aivCoreLimit = numBlocksLimit;
1253	    }
1254	
1255	    CHK_RET(HcclGetCommName(comm, exchangeInfo.group));
