1271	HcclResult FillOpExchangeInfoWithDataDes(const OpParam& param, OpExchangeInfo& exchangeInfo)
1272	{
1273	    switch (param.opType) {
1274	        case HcclCMDType::HCCL_CMD_BATCH_SEND_RECV:
1275	            break;
1276	        case HcclCMDType::HCCL_CMD_ALLTOALL:
1277	            exchangeInfo.dataType = param.all2AllVDataDes.sendType;
1278	            CHK_PTR_NULL(param.all2AllVDataDes.sendCounts);
1279	            exchangeInfo.count = static_cast<u64*>(param.all2AllVDataDes.sendCounts)[0];
1280	            break;
1281	        case HcclCMDType::HCCL_CMD_ALLTOALLV:
1282	        case HcclCMDType::HCCL_CMD_ALLTOALLVC:
1283	            exchangeInfo.dataType = param.all2AllVDataDes.sendType;
1284	            break;
1285	        case HcclCMDType::HCCL_CMD_ALLGATHER_V:
1286	        case HcclCMDType::HCCL_CMD_REDUCE_SCATTER_V:
1287	            exchangeInfo.dataType = param.vDataDes.dataType;
1288	            break;
1289	        default:
1290	            exchangeInfo.dataType = param.DataDes.dataType;
1291	            exchangeInfo.count = param.DataDes.count;
1292	            break;
1293	    }
1294	    return HCCL_SUCCESS;
1295	}
