1350	HcclResult CacheHostCtxToEngine(
1351	    HcclComm comm, const char* algTag, const std::string& hostCacheTag, const std::vector<char>& hostCtxSeq)
1352	{
1353	    void* hostCtxPtr = nullptr;
1354	    HcclResult createRet = HcclEngineCtxCreate(
1355	        comm, hostCacheTag.c_str(), CommEngine::COMM_ENGINE_CPU_TS, hostCtxSeq.size(), &hostCtxPtr);
1356	    if (createRet != HCCL_SUCCESS) {
1357	        HCCL_ERROR("failed to create host EngineCtx for caching, ret[%d].", createRet);
1358	        HcclResult destroyRet = HcclEngineCtxDestroy(comm, algTag, COMM_ENGINE_AICPU_TS);
1359	        if (destroyRet != HCCL_SUCCESS) {
1360	            HCCL_ERROR("failed to destroy device ctx on host ctx create failure rollback, ret[%d].", destroyRet);
1361	        }
1362	        return createRet;
1363	    }
1364	    errno_t memcpyRet = memcpy_s(hostCtxPtr, hostCtxSeq.size(), hostCtxSeq.data(), hostCtxSeq.size());
1365	    if (memcpyRet != EOK) {
1366	        HCCL_ERROR("memcpy_s failed writing to host EngineCtx cache, ret=%d.", memcpyRet);
1367	        HcclEngineCtxDestroy(comm, hostCacheTag.c_str(), CommEngine::COMM_ENGINE_CPU_TS);
1368	        HcclEngineCtxDestroy(comm, algTag, COMM_ENGINE_AICPU_TS);
1369	        return HCCL_E_INTERNAL;
1370	    }
1371	    return HCCL_SUCCESS;
1372	}
