1393	HcclResult IncrementalCreateChannel(
1394	    HcclComm comm, const OpParam& param, AlgResourceRequest& resRequest, AlgResourceCtxSerializable& hostCtxObj,
1395	    const std::string& hostCacheTag, void** resCtxSequence, uint64_t& ctxSize)
1396	{
1397	    HcclResult ret = HcclGetChannel(comm, param, resRequest, &hostCtxObj);
1398	    CHK_PRT_RET(ret != HCCL_SUCCESS, HCCL_ERROR("failed to incrementally create channel."), ret);
1399	    if (param.engine == COMM_ENGINE_CPU) {
1400	        ret = HcclEngineCtxDestroy(comm, param.algTag, COMM_ENGINE_AICPU_TS);
1401	    } else {
1402	        ret = HcclEngineCtxDestroy(comm, param.algTag, param.engine);
1403	    }
1404	    if (ret != HCCL_SUCCESS) {
1405	        HCCL_ERROR("failed to destroy device Ctx, ret[%d].", ret);
1406	    }
1407	    std::vector<char> newSeq = hostCtxObj.Serialize();
1408	    ret = HcclMemcpyCtxHostToDevice(comm, param, newSeq, resCtxSequence, ctxSize);
1409	    if (ret != HCCL_SUCCESS) {
1410	        HCCL_ERROR("failed to memcpy hostCtx to device after incremental channel creation, ret[%d].", ret);
1411	        HcclResult destroyRet = HcclEngineCtxDestroy(comm, hostCacheTag.c_str(), CommEngine::COMM_ENGINE_CPU_TS);
1412	        if (destroyRet != HCCL_SUCCESS) {
1413	            HCCL_ERROR("failed to destroy host ctx on incremental path failure rollback, ret[%d].", destroyRet);
1414	        }
1415	        return ret;
1416	    }
1417	    HcclResult destroyRet = HcclEngineCtxDestroy(comm, hostCacheTag.c_str(), CommEngine::COMM_ENGINE_CPU_TS);
1418	    if (destroyRet != HCCL_SUCCESS) {
1419	        HCCL_ERROR("failed to destroy old host EngineCtx for cache update, ret[%d].", destroyRet);
1420	    }
1421	    void* newHostCtxPtr = nullptr;
1422	    HcclResult cacheRet = HcclEngineCtxCreate(
1423	        comm, hostCacheTag.c_str(), CommEngine::COMM_ENGINE_CPU_TS, newSeq.size(), &newHostCtxPtr);
1424	    if (cacheRet != HCCL_SUCCESS) {
1425	        HCCL_ERROR("failed to create host EngineCtx for cache update, ret[%d].", cacheRet);
1426	        HcclResult devDestroyRet = HcclEngineCtxDestroy(comm, param.algTag, param.engine);
1427	        if (devDestroyRet != HCCL_SUCCESS) {
1428	            HCCL_ERROR("failed to destroy device ctx on host cache update failure rollback, ret[%d].", devDestroyRet);
1429	        }
1430	        return cacheRet;
1431	    }
1432	    errno_t memcpyRet = memcpy_s(newHostCtxPtr, newSeq.size(), newSeq.data(), newSeq.size());
1433	    if (memcpyRet != EOK) {
1434	        HCCL_ERROR("memcpy_s failed writing to updated host EngineCtx cache, ret=%d.", memcpyRet);
1435	        HcclEngineCtxDestroy(comm, hostCacheTag.c_str(), CommEngine::COMM_ENGINE_CPU_TS);
1436	        HcclEngineCtxDestroy(comm, param.algTag, param.engine);
1437	        return HCCL_E_INTERNAL;
1438	    }
1439	    HCCL_INFO("Incrementally add channel success");
1440	    return HCCL_SUCCESS;
1441	}
