1481	HcclResult HcclMemcpyCtxHostToDevice(
1482	    HcclComm comm, const OpParam& param, const std::vector<char>& seq, void** resCtxSequence, uint64_t& ctxSize)
1483	{
1484	    uint64_t size = seq.size();
1485	    void* ctx = nullptr;
