1487	    CHK_RET(HcclEngineCtxCreate(comm, param.algTag, COMM_ENGINE_AICPU_TS, size, &ctx));
1488	    // 从Host内存拷贝到Device Context内存上
1489	    CHK_RET(HcclEngineCtxCopy(comm, COMM_ENGINE_AICPU_TS, param.algTag, seq.data(), size, 0));
1490	    // 将内存强转为AlgResourceCtx结构体
1491	    *resCtxSequence = ctx;
1492	    ctxSize = size;
1493	    HCCL_INFO("Memcpy hostCtx to device success.");
1494	    return HCCL_SUCCESS;
1495	}
