1517	static HcclResult HcclGetThreadWithConfig(
1518	    HcclComm comm, const OpParam& param, AlgResourceRequest& resRequest, u32 threadNum,
1519	    std::vector<ThreadHandle>& threads, std::unique_ptr<AlgResourceCtxSerializable>& resCtxHost, bool unfoldReady)
1520	{
1521	    std::vector<ThreadConfig> threadConfigs(threadNum);
1522	    CHK_RET(static_cast<HcclResult>(ThreadConfigInit(threadConfigs.data(), threadNum)));
1523	    threadConfigs[0].notifyNumPerThread = resRequest.notifyNumOnMainThread + 1; // 主流上多一个用于host-device同步
1524	    HCCL_DEBUG("[HcclGetThread] AICPU thread[0] notify num[%u].", threadConfigs[0].notifyNumPerThread);
1525	    CHK_PRT_RET(
1526	        resRequest.notifyNumPerThread.size() < threadNum - 1,
1527	        HCCL_ERROR(
1528	            "[HcclGetThread] notifyNumPerThread size[%zu] is less than slaveThreadNum[%u].",
1529	            resRequest.notifyNumPerThread.size(), threadNum - 1),
1530	        HCCL_E_INTERNAL);
1531	    for (u32 i = 1; i < threadNum; i++) {
1532	        threadConfigs[i].notifyNumPerThread = resRequest.notifyNumPerThread[i - 1];
1533	        HCCL_DEBUG("[HcclGetThread] AICPU thread[%u] notify num[%u].", i, threadConfigs[i].notifyNumPerThread);
1534	    }
1535	    CHK_RET(HcclThreadAcquireWithConfig(
1536	        comm, COMM_ENGINE_AICPU, threadNum, THREAD_TYPE_TS, threadConfigs.data(), threads.data()));
1537	    // 申请展开流对应的Thread
1538	    if (!unfoldReady) {
1539	        ThreadConfig unfoldThreadConfig;
1540	        CHK_RET(static_cast<HcclResult>(ThreadConfigInit(&unfoldThreadConfig, 1)));
1541	        // 展开流需要一个Notify用于 AICPU按序下发
1542	        unfoldThreadConfig.notifyNumPerThread = ORDER_UNFOLD_THREAD_NOTIFY_NUM;
1543	        CHK_RET(HcclThreadAcquireWithConfig(
1544	            comm, COMM_ENGINE_CPU, 1, THREAD_TYPE_TS, &unfoldThreadConfig, &resCtxHost->unfoldThread));
1545	    }
1546	    CHK_RET(SaveMainThreadInfo(comm, param, threads[0], resRequest.notifyNumOnMainThread + 1));
1547	    return HCCL_SUCCESS;
1548	}
