1550	static u32 GetMaxNotifyNum(const std::vector<u32>& notifyNumPerThread, u32 initNotifyNum)
1551	{
1552	    u32 maxNotifyNum = initNotifyNum;
1553	    for (u32 notifyNum : notifyNumPerThread) {
1554	        if (notifyNum > maxNotifyNum) {
1555	            maxNotifyNum = notifyNum;
1556	        }
1557	    }
1558	    return maxNotifyNum;
1559	}
