1561	static HcclResult HcclGetAicpuThread(
1562	    HcclComm comm, const OpParam& param, AlgResourceRequest& resRequest,
1563	    std::unique_ptr<AlgResourceCtxSerializable>& resCtxHost)
1564	{
1565	    u32 threadNum = resRequest.slaveThreadNum + 1;
1566	    std::vector<ThreadHandle> threads(threadNum);
1567	    bool unfoldReady = false;
1568	    ThreadHandle existingUnfoldThread = 0;
1569	    if (GetUnfoldThreadInfo(comm, param, existingUnfoldThread) == HCCL_SUCCESS) {
1570	        resCtxHost->unfoldThread = existingUnfoldThread;
1571	        unfoldReady = true;
1572	        HCCL_INFO("[HcclGetThread] reuse unfoldThread [%lu]", resCtxHost->unfoldThread);
1573	    }
1574	    if (HcommIsSupportHcclThreadAcquireWithConfig()) {
1575	        CHK_RET(HcclGetThreadWithConfig(comm, param, resRequest, threadNum, threads, resCtxHost, unfoldReady));
1576	    } else {
1577	        u32 maxNotifyNum = GetMaxNotifyNum(resRequest.notifyNumPerThread, resRequest.notifyNumOnMainThread);
1578	        HCCL_DEBUG("[HcclGetThread] require maxNotifyNum[%u] for all AICPU threads.", maxNotifyNum);
1579	        CHK_RET(HcclThreadAcquire(comm, COMM_ENGINE_AICPU_TS, threadNum, maxNotifyNum + 1, threads.data()));
1580	        if (!unfoldReady) {
1581	            // 展开流需要一个Notify用于 AICPU按序下发
1582	            CHK_RET(
1583	                HcclThreadAcquire(comm, COMM_ENGINE_CPU, 1, ORDER_UNFOLD_THREAD_NOTIFY_NUM, &resCtxHost->unfoldThread));
1584	        }
1585	        CHK_RET(SaveMainThreadInfo(comm, param, threads[0], maxNotifyNum + 1));
1586	    }
1587	    if (!unfoldReady) {
1588	        CHK_RET(SaveUnfoldThreadInfo(comm, param, resCtxHost->unfoldThread));
1589	    }
1590	    HCCL_INFO("[HcclGetThread] unfoldThread [%lu]", resCtxHost->unfoldThread);
1591	    HCCL_DEBUG("threads ptr is %p\n", threads.data());
1592	    for (u32 i = 0; i < threadNum; i++) {
1593	        resCtxHost->threads.push_back(threads[i]);
1594	    }
1595	    return HCCL_SUCCESS;
1596	}
