1598	HcclResult HcclGetThread(
1599	    HcclComm comm, const OpParam& param, AlgResourceRequest& resRequest,
1600	    std::unique_ptr<AlgResourceCtxSerializable>& resCtxHost, const ResPackGraphMode& resPack)
1601	{
1602	    resCtxHost->isHcclThreadAcquireWithConfigSupported = HcommIsSupportHcclThreadAcquireWithConfig();
1603	    if ((param.engine == COMM_ENGINE_AICPU_TS) || (param.engine == COMM_ENGINE_CPU)) {
1604	        CHK_RET(HcclGetAicpuThread(comm, param, resRequest, resCtxHost));
1605	    } else {
1606	        // host模式下，将主流封装为thread，并创建主流上的notify
1607	        ThreadHandle thread;
1608	        CHK_RET(
1609	            HcclThreadAcquireWithStream(comm, param.engine, param.stream, resRequest.notifyNumOnMainThread, &thread));
1610	        resCtxHost->threads.push_back(thread);
1611	
1612	        u32 maxNotifyNum = GetMaxNotifyNum(resRequest.notifyNumPerThread, 0);
1613	        CHK_RET(GeGetThread(comm, param, resRequest, resCtxHost, resPack, maxNotifyNum));
1614	    }
1615	
1616	    if (UNLIKELY(HcclCheckLogLevel(DLOG_DEBUG))) {
1617	        HCCL_DEBUG("[HcclGetThread] slaveThreadNum[%u]", resRequest.slaveThreadNum);
1618	        for (u32 i = 0; i < resRequest.slaveThreadNum + 1; i++) {
1619	            HCCL_DEBUG("[HcclGetThread] threads[%u]=[%llu]", i, resCtxHost->threads[i]);
1620	        }
1621	    }
1622	    return HCCL_SUCCESS;
1623	}
