1625	HcclResult GeGetThread(
1626	    HcclComm comm, const OpParam& param, AlgResourceRequest& resRequest,
1627	    std::unique_ptr<AlgResourceCtxSerializable>& resCtxHost, const ResPackGraphMode& resPack, u32 maxNotifyNum)
1628	{
1629	    if (param.opMode == OpMode::OPBASE) {
1630	        u32 threadNum = resRequest.slaveThreadNum;
1631	        if (threadNum > 0) {
1632	            std::vector<ThreadHandle> threads(threadNum);
1633	            if (HcommIsSupportHcclThreadAcquireWithConfig()) {
1634	                std::vector<ThreadConfig> threadConfigs(threadNum);
1635	                CHK_RET(static_cast<HcclResult>(ThreadConfigInit(threadConfigs.data(), threadNum)));
1636	                CHK_PRT_RET(
1637	                    resRequest.notifyNumPerThread.size() < threadNum,
1638	                    HCCL_ERROR(
1639	                        "[GeGetThread] notifyNumPerThread size[%zu] is less than slaveThreadNum[%u].",
1640	                        resRequest.notifyNumPerThread.size(), threadNum),
1641	                    HCCL_E_INTERNAL);
1642	                for (u32 i = 0; i < threadNum; i++) {
1643	                    threadConfigs[i].notifyNumPerThread = resRequest.notifyNumPerThread[i];
1644	                }
1645	                CHK_RET(HcclThreadAcquireWithConfig(
1646	                    comm, COMM_ENGINE_CPU, threadNum, THREAD_TYPE_TS, threadConfigs.data(), threads.data()));
1647	            } else {
1648	                CHK_RET(HcclThreadAcquire(comm, param.engine, threadNum, maxNotifyNum, threads.data()));
1649	            }
1650	            for (u32 i = 0; i < threadNum; i++) {
1651	                resCtxHost->threads.push_back(threads[i]);
1652	            }
1653	        }
1654	    } else {
1655	        u32 slaveStreams = resPack.streams.size();
1656	        u32 threadNum = resRequest.slaveThreadNum;
1657	        if (threadNum > slaveStreams) {
1658	            HCCL_ERROR(
1659	                "Thread Num Should less than slave streams. slaveStreams[%llu], threadNums[%llu]", slaveStreams,
1660	                threadNum);
1661	            return HCCL_E_UNAVAIL;
1662	        }
1663	
1664	        for (u32 i = 0; i < threadNum; i++) {
1665	            ThreadHandle slaveThread;
1666	            CHK_RET(HcclThreadAcquireWithStream(comm, param.engine, resPack.streams[i], maxNotifyNum, &slaveThread));
1667	            resCtxHost->threads.push_back(slaveThread);
1668	        }
1669	    }
1670	
1671	    return HCCL_SUCCESS;
1672	}
