1674	HcclResult SaveMainThreadInfo(HcclComm comm, const OpParam& param, ThreadHandle thread, u32 notifyNum)
1675	{
1676	    uint64_t size = sizeof(ThreadHandle) + sizeof(u32);
1677	    void* ctx = nullptr;
1678	    // 申请一块host类型内存，保存主流信息
1679	    CHK_RET(HcclEngineCtxCreate(comm, param.algTag, CommEngine::COMM_ENGINE_CPU_TS, size, &ctx));
1680	    // 填充主流handle信息
1681	    ThreadHandle* threadPtr = reinterpret_cast<ThreadHandle*>(ctx);
1682	    *threadPtr = thread;
