1684	    char* curPtr = reinterpret_cast<char*>(ctx);
1685	    curPtr += sizeof(ThreadHandle);
1686	    u32* notifyNumPtr = reinterpret_cast<u32*>(curPtr);
1687	    *notifyNumPtr = notifyNum;
1688	    HCCL_INFO(
1689	        "[SaveMainThreadInfo]threadPtr[%p], thread[%lu], notifyNumPtr[%p], notifyNum[%lu]", threadPtr, thread,
1690	        notifyNumPtr, notifyNum);
1691	    return HCCL_SUCCESS;
1692	}
