1694	HcclResult SaveUnfoldThreadInfo(HcclComm comm, const OpParam& param, ThreadHandle unfoldThread)
1695	{
1696	    uint64_t size = sizeof(ThreadHandle);
1697	    void* ctx = nullptr;
1698	    // 申请一块host类型内存，保存展开流信息
1699	    char unfoldAlgTag[ALG_TAG_LENGTH] = {0};
1700	    int ret = snprintf_s(unfoldAlgTag, sizeof(unfoldAlgTag), sizeof(unfoldAlgTag) - 1, "%s_unfold", param.commName);
1701	    CHK_PRT_RET(ret <= 0, HCCL_ERROR("[%s] failed to fill unfoldAlgTag", __func__), HCCL_E_INTERNAL);
