106	u32 AutoSelectorBase::CalcFrameNum(const TopoInfoWithNetLayerDetails* topoInfo) const
107	{
108	    u32 frameNum = 0;
109	    if (topoInfo->topoLevelNums <= 1 || topoInfo->netLayerDetails.instSizeListOfLayer[0].empty()) {
110	        return frameNum;
111	    }
112	    u32 gcd = topoInfo->netLayerDetails.instSizeListOfLayer[0][0];
113	    for (size_t i = 1; i < topoInfo->netLayerDetails.instSizeListOfLayer[0].size(); ++i) {
114	        u32 a = gcd;
115	        u32 b = topoInfo->netLayerDetails.instSizeListOfLayer[0][i];
116	        while (b != 0) {
117	            u32 r = a % b;
118	            a = b;
119	            b = r;
120	        }
121	        gcd = a;
122	        if (gcd == 1) {
123	            break;
124	        }
125	    }
126	    frameNum = (gcd > 0) ? topoInfo->userRankSize / gcd : 0;
127	    return frameNum;
128	}
