211	HcclResult
212	AutoSelectorBase::CheckMeshNumEqualToClosNum(const TopoInfoWithNetLayerDetails* topoInfo, bool& isEqual) const
213	{
214	    const auto& topoInstDetails = topoInfo->topoInstDetailsOfLayer;
215	
216	    // 检查topoInstDetails是否为空
217	    CHK_PRT_RET(
218	        topoInstDetails.empty(),
219	        HCCL_ERROR("[BaseSelector][CheckMeshNumEqualToClosNum] topoInstDetailsOfLayer0 size is zero."),
220	        HCCL_E_INTERNAL);
221	
222	    const auto& rankNumMap = topoInstDetails[0].rankNumForTopoType;
223	    auto closItr = rankNumMap.find(COMM_TOPO_CLOS);
224	    auto meshItr = rankNumMap.find(COMM_TOPO_1DMESH);
225	    CHK_PRT_RET(
226	        closItr == rankNumMap.end() || closItr->second.empty() || meshItr == rankNumMap.end()
227	            || meshItr->second.empty(),
228	        HCCL_ERROR("[BaseSelector][CheckMeshNumEqualToClosNum] topoInstDetailsOfLayer0 size is zero."),
229	        HCCL_E_INTERNAL);
230	
231	    // 获取CLOS和1DMESH拓扑的rank数量并比较是否相等
232	    isEqual = (closItr->second[0] == meshItr->second[0]);
233	    return HCCL_SUCCESS;
234	}
