349	bool AutoSelectorBase::ProcessAivConfig(
350	    OpParam& opParam, TopoInfoWithNetLayerDetails* topoInfo,
351	    const std::map<HcclCMDType, std::vector<HcclAlgoType>>& configAlgMap, std::string& selectAlgName,
352	    SelectorStatus& ret) const
353	{
354	    if (opParam.opExecuteConfig != OpExecuteConfig::AIV && opParam.opExecuteConfig != OpExecuteConfig::AIV_ONLY) {
355	        return false;
356	    }
357	
358	    ret = SelectAivAlgo(topoInfo, opParam, configAlgMap, selectAlgName);
359	    if (ret == SelectorStatus::NOT_MATCH) {
360	        if (opParam.opExecuteConfig == OpExecuteConfig::AIV_ONLY) {
361	            return true;
362	        }
363	        opParam.opExecuteConfig = OpExecuteConfig::CCU_FAIL;
364	        return false;
365	    }
366	
367	    return true;
368	}
