401	SelectorStatus AllReduceAutoSelector::SelectAicpuAlgo(
402	    const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam,
403	    const std::map<HcclCMDType, std::vector<HcclAlgoType>>& configAlgMap, std::string& selectAlgName) const
404	{
405	    HCCL_DEBUG("[AllReduceAutoSelector][%s] start, topoInfo levelNum[%u]", __func__, topoInfo->topoLevelNums);
406	    u64 perDataSize = DATATYPE_SIZE_TABLE[opParam.DataDes.dataType];
407	    u64 dataSize = opParam.DataDes.count * perDataSize;
408	
409	    if (IsNeedStrictModeForOrderPreserved(opParam, topoInfo->userRankSize)) {
410	        if (topoInfo->userRankSize > MAX_RANK_NUM_FOR_ORDER_PRESERVED) {
411	            // 内部reducescatter中采用分组all2all + NHR 算法
412	            selectAlgName = "AllReduceOrderPreservedGroup";
413	        } else {
414	            // 内部reducescatter中采用非分组all2all + mesh1D 算法
415	            selectAlgName = "AicpuAllReduceStrictOrderedMesh";
416	        }
417	        HCCL_INFO(
418	            "[AllReduceAutoSelector] DETERMINISTIC_STRICT mode, rankSize[%u], threshold[%u], "
419	            "select [%s]",
420	            topoInfo->userRankSize, MAX_RANK_NUM_FOR_ORDER_PRESERVED, selectAlgName.c_str());
421	        return SelectorStatus::MATCH;
422	    }
423	
424	    bool isDataTypeOrReduceTypeSpecial = opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_INT64
425	                                         || opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_UINT64
426	                                         || opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_FP64
427	                                         || opParam.reduceType == HcclReduceOp::HCCL_REDUCE_PROD;
428	
429	    if (topoInfo->topoLevelNums > 1) {
430	        if (isDataTypeOrReduceTypeSpecial) {
431	            selectAlgName = "AicpuAllReduceSoleNHRAicpuReduce";
432	        } else if (topoInfo->topoLevelNums == TOPO_LEVEL_NUM_3 && topoInfo->level2Uboe) {
433	            bool level0AndLevel1Symetric = topoInfo->level0Symmetric && topoInfo->level1Symmetric;
434	            if (level0AndLevel1Symetric && topoInfo->deviceNumPerModule == DEVICE_NUM_PER_MODULE_8) {
435	                selectAlgName = "AicpuAllReducePipeLine";
436	            } else if (!level0AndLevel1Symetric || topoInfo->netLayerDetails.localNetInsSizeOfLayer[1] == 1) {
437	                selectAlgName = "AicpuAllReduceSoleNHR";
438	            } else {
439	                selectAlgName = "InsAllReduceParallelRSAGUboe";
440	            }
441	        } else if (topoInfo->Level1Nhr) {
442	            // Level1Nhr 已在 CalcTopoShape 中设置（GCD==1 时为 true）
443	            selectAlgName = "AicpuAllReduceSoleNHR";
444	            HCCL_INFO("[AllReduceAutoSelector] Level1Nhr=true, select [%s]", selectAlgName.c_str());
445	        } else if (topoInfo->netLayerDetails.localNetInsSizeOfLayer[0] == 1) {
446	            selectAlgName = "AicpuAllReduceSoleNHR";
447	        } else if (topoInfo->level0Topo == Level0Shape::MESH_1D) {
448	            if (topoInfo->topoLevelNums == TOPO_LEVEL_NUM_3) {
449	                selectAlgName = "AicpuAllReduceSequenceMeshConcurNHRNHR";
450	            } else if (topoInfo->topoLevelNums == TOPO_LEVEL_NUM_2) {
451	                if (dataSize > AR_AICPU_1D_CROSS_SMALL_DATA_SIZE) {
452	                    selectAlgName = (dataSize > AR_AICPU_SEQUENCE_DATA_SIZE) ? "AicpuAllReduceSequenceMeshConcurNHR" :
453	                                                                               "AicpuAllReduceParallelMeshNHR";
454	                } else {
455	                    selectAlgName = "AicpuAllReduceSoleNHR";
456	                }
457	            } else {
458	                selectAlgName = "AicpuAllReduceSoleNHR";
459	            }
460	        } else if (topoInfo->level0Topo == Level0Shape::CLOS) {
461	            selectAlgName = "AicpuAllReduceSoleNHRTwoShotMultiLink";
462	        } else {
463	            return SelectorStatus::NOT_MATCH;
464	        }
465	    } else {
466	        return SelectMeshAlgoAicpu(topoInfo, opParam, selectAlgName);
467	    }
468	
469	    HCCL_DEBUG("[AllReduceAutoSelector][%s] Algo match [%s]", __func__, selectAlgName.c_str());
470	    return SelectorStatus::MATCH;
471	}
