503	        selectAlgName = "AicpuAllReduceSoleNHR";
504	    }
505	
506	    HCCL_DEBUG("[AllReduceAutoSelector][%s] Algo match [%s]", __func__, selectAlgName.c_str());
507	    return SelectorStatus::MATCH;
