510	SelectorStatus AllReduceAutoSelector::SelectMeshAlgoAicpu(
511	    const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam, std::string& selectAlgName) const
512	{
513	    u64 perDataSize = DATATYPE_SIZE_TABLE[opParam.DataDes.dataType];
514	    u64 dataSize = opParam.DataDes.count * perDataSize;
515	
516	    bool isDataTypeOrReduceTypeSpecial = opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_INT64
517	                                         || opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_UINT64
518	                                         || opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_FP64
519	                                         || opParam.reduceType == HcclReduceOp::HCCL_REDUCE_PROD;
520	
521	    double ratio;
522	    if (topoInfo->userRankSize == 0) {
523	        HCCL_WARNING("[AllReduceAutoSelector] the selector userRankSize not set");
524	        ratio = 1;
525	    } else {
526	        ratio = DEFAULT_RANK_SIZE / topoInfo->userRankSize / topoInfo->userRankSize;
527	    }
528	    bool isTwoLevelFlag = IsTwoLevelNetLayer(topoInfo, opParam);
529	    bool overSequenceDataThreshold = dataSize > AR_AICPU_SEQUENCE_DATA_SIZE;
530	    if (topoInfo->level0Topo == Level0Shape::MESH_1D) {
531	        if (isDataTypeOrReduceTypeSpecial) {
532	            selectAlgName = dataSize <= AR_AICPU_1D_64DATATYPE_DATA_SIZE ? "AicpuAllReduceSoleMeshOneShot" :
533	                                                                           "AicpuAllReduceSoleMeshTwoShot";
534	        } else if (isTwoLevelFlag && topoInfo->userRankSize == 2 && dataSize >= AR_2P_DETOUR_DATA_SIZE) {
535	            // 两p条件下生效
536	            selectAlgName = "AicpuAllReduceSoleMeshConcur";
537	        } else if (dataSize <= AR_AICPU_1D_SMALL_DATA_SIZE) {
538	            selectAlgName = "AicpuAllReduceSoleMeshOneShot";
539	        } else if (dataSize * ratio > AR_AICPU_1D_MAX_DATA_SIZE) {
540	            selectAlgName = (isTwoLevelFlag && overSequenceDataThreshold) ? "AicpuAllReduceSoleMeshConcur" :
541	                                                                            "AicpuAllReduceSoleMeshChunkTwoShot";
542	        } else {
543	            selectAlgName = "AicpuAllReduceSoleMeshTwoShot";
544	        }
545	    } else if (topoInfo->level0Topo == Level0Shape::CLOS) {
546	        if (isDataTypeOrReduceTypeSpecial) {
547	            selectAlgName = "AicpuAllReduceSoleNHRAicpuReduce";
548	        } else {
549	            selectAlgName = "AicpuAllReduceSoleNHRTwoShotMultiLink";
550	        }
551	    } else if (topoInfo->level0Topo == Level0Shape::MESH_1D_CLOS) {
552	        if (topoInfo->level0PcieMix) {
553	            if (IsLayerAllConnetedWithTopo(topoInfo, 0, CommTopo::COMM_TOPO_1DMESH)) {
554	                if (isDataTypeOrReduceTypeSpecial) {
555	                    selectAlgName = dataSize <= AR_AICPU_1D_64DATATYPE_DATA_SIZE ? "AicpuAllReduceSoleMeshOneShot" :
556	                                                                                   "AicpuAllReduceSoleMeshTwoShot";
557	                } else if (dataSize <= AR_AICPU_1D_SMALL_DATA_SIZE) {
558	                    selectAlgName = "AicpuAllReduceSoleMeshOneShot";
559	                } else if (dataSize * ratio > AR_AICPU_1D_MAX_DATA_SIZE) {
560	                    selectAlgName = "AicpuAllReduceSoleMeshChunkTwoShot";
561	                } else {
562	                    selectAlgName = "AicpuAllReduceSoleMeshTwoShot";
563	                }
564	            } else {
565	                if (isDataTypeOrReduceTypeSpecial) {
566	                    selectAlgName = "AicpuAllReduceSoleNHRAicpuReduce";
567	                } else {
568	                    selectAlgName = (dataSize < OMNI_PCIE_AR_DATA_SIZE) ? "InsAllReduceParallelMesh1DNHRPcie" :
569	                                                                          "AicpuAllReducePipeLinePcie";
570	                }
571	            }
572	        } else {
573	            return SelectMeshAlgoAicpuUBX(topoInfo, dataSize, selectAlgName, isDataTypeOrReduceTypeSpecial);
574	        }
575	    } else {
576	        HCCL_ERROR("[AllReduceAutoSelector] topo not match");
577	        return SelectorStatus::NOT_MATCH;
578	    }
579	
580	    HCCL_DEBUG("[AllReduceAutoSelector][%s] Algo match [%s]", __func__, selectAlgName.c_str());
581	    return SelectorStatus::MATCH;
582	}
583	
584	SelectorStatus AllReduceAutoSelector::SelectAivAlgo(
585	    const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam,
586	    const std::map<HcclCMDType, std::vector<HcclAlgoType>>& configAlgMap, std::string& selectAlgName) const
587	{
588	    (void)configAlgMap;
589	    HCCL_DEBUG("[Algo][AllReduceAutoSelector][%s] start, topoInfo levelNum[%u]", __func__, topoInfo->topoLevelNums);
590	
591	    if (topoInfo->level2Ubg) {
592	        HCCL_AIV_NOT_MATCH_LOG(
593	            opParam, HCCL_DEBUG, "[AllReduceAutoSelector][%s] aiv is not supported with level2Ubg, reset to default.",
594	            __func__);
595	        return SelectorStatus::NOT_MATCH;
596	    }
597	
598	    if (topoInfo->topoLevelNums >= TOPO_LEVEL_NUM_3) {
599	        HCCL_AIV_NOT_MATCH_LOG(
600	            opParam, HCCL_DEBUG,
601	            "[AllReduceAutoSelector][%s] aiv is not supported when topoLevelNums >= 3(levelNum[%u]), reset to default.",
602	            __func__, topoInfo->topoLevelNums);
603	        return SelectorStatus::NOT_MATCH;
604	    }
605	
606	    // 保序模式不支持AIV，需要回退到AICPU
607	    CHK_PRT_RET(
608	        IsNeedStrictModeForOrderPreserved(opParam, topoInfo->userRankSize),
609	        HCCL_AIV_NOT_MATCH_LOG(
610	            opParam, HCCL_DEBUG,
611	            "[Algo][AllReduceAutoSelector] DETERMINISTIC_STRICT mode is not supported yet for AIV mode."),
612	        SelectorStatus::NOT_MATCH);
613	
614	    // aiv 模式不支持 PROD
615	    CHK_PRT_RET(
616	        opParam.reduceType == HcclReduceOp::HCCL_REDUCE_PROD,
617	        HCCL_AIV_NOT_MATCH_LOG(
618	            opParam, HCCL_DEBUG, "[Algo][AllReduceAutoSelector] ReduceOp[%d] is not supported yet for aiv mode.",
619	            opParam.reduceType),
620	        SelectorStatus::NOT_MATCH);
621	
622	    if (opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_UINT64
623	        || opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_FP64) {
624	        HCCL_AIV_NOT_MATCH_LOG(opParam, HCCL_DEBUG, "[Algo][AllReduceAutoSelector] aiv mode not support UINT64, FP64.");
625	        return SelectorStatus::NOT_MATCH;
626	    }
627	
628	    if (topoInfo->userRankSize > MAX_RANK_SIZE) {
629	        HCCL_AIV_NOT_MATCH_LOG(
630	            opParam, HCCL_DEBUG, "[AllReduceAutoSelector] rankSize[%u] larger than [%u]", topoInfo->userRankSize,
631	            MAX_RANK_SIZE);
632	        return SelectorStatus::NOT_MATCH;
633	    }
634	
635	    void* cclBufferAddr;
636	    uint64_t cclBufferSize;
637	    CHK_PRT_RET(
638	        HcclGetHcclBuffer(opParam.hcclComm, &cclBufferAddr, &cclBufferSize) != HCCL_SUCCESS,
639	        HCCL_AIV_NOT_MATCH_LOG(opParam, HCCL_WARNING, "[AllReduceAutoSelector] HcclGetHcclBuffer failed."),
640	        SelectorStatus::NOT_MATCH);
641	    u64 perDataSize = DATATYPE_SIZE_TABLE[opParam.DataDes.dataType];
642	    u64 dataSize = opParam.DataDes.count * perDataSize;
643	    if (opParam.opExecuteConfig != OpExecuteConfig::AIV_ONLY
644	        && dataSize >= AIV_MAX_PER_RANK_DATA_SIZE * topoInfo->userRankSize) {
645	        HCCL_DEBUG(
646	            "[AllReduceAutoSelector][%s] dataSize[%llu] larger than AIV_MAX_PER_RANK_DATA_SIZE[%llu] * rankSize[%u]",
647	            __func__, dataSize, AIV_MAX_PER_RANK_DATA_SIZE, topoInfo->userRankSize);
648	        return SelectorStatus::NOT_MATCH;
649	    }
650	    if (dataSize > cclBufferSize * AIV_MAX_CCL_LOOP_NUM) {
651	        HCCL_AIV_NOT_MATCH_LOG(
652	            opParam, HCCL_DEBUG, "[AllReduceAutoSelector][%s] dataSize[%llu] too large for cclBufferSize [%llu]",
653	            __func__, dataSize, cclBufferSize);
654	        return SelectorStatus::NOT_MATCH;
655	    }
656	
657	    if (topoInfo->level0Topo != Level0Shape::MESH_1D) {
658	        selectAlgName = "AivAllReduceSoleMeshTwoShot";
659	    } else if (topoInfo->userRankSize <= AR_AIV_BOARD_SIZE) {
660	        // 板内8p场景，按照时延拐点选择算法
661	        if (dataSize < AR_AIV_SMALL_DATA_SIZE_IN_BOARD) {
662	            selectAlgName = "AivAllReduceSoleMeshOneShot";
663	        } else {
664	            selectAlgName = "AivAllReduceSoleMeshTwoShot";
665	        }
666	    } else {
667	        if (IsSmallData(dataSize)) {
668	            selectAlgName = "AivAllReduceSoleMeshOneShot";
669	        } else {
670	            selectAlgName = "AivAllReduceSoleMeshTwoShot";
671	        }
672	    }
673	
674	    HCCL_DEBUG("[AllReduceAutoSelector][%s] Algo match [%s]", __func__, selectAlgName.c_str());
675	    return SelectorStatus::MATCH;
676	}
677	
678	SelectorStatus AllReduceAutoSelector::SelectDPUAlgo(
679	    const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam,
680	    const std::map<HcclCMDType, std::vector<HcclAlgoType>>& configAlgMap, std::string& selectAlgName) const
681	{
682	    std::vector<HcclAlgoType> algos
683	        = std::vector<HcclAlgoType>(HCCL_ALGO_LEVEL_NUM, HcclAlgoType::HCCL_ALGO_TYPE_DEFAULT);
684	    auto it = configAlgMap.find(opParam.opType);
685	    if ((it != configAlgMap.end()) && (it->second.size() > 1)) {
686	        algos = it->second;
687	    }
688	
689	    HCCL_INFO(
690	        "hccl algo op config: config opType:%d, level0:%u, level1:%u, level2:%u, level3:%u", opParam.opType, algos[0],
691	        algos[1], algos[2], algos[3]);
692	    bool isDataTypeOrReduceTypeSpecial = opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_INT64
693	                                         || opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_UINT64
694	                                         || opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_FP64
695	                                         || opParam.reduceType == HcclReduceOp::HCCL_REDUCE_PROD;
696	    if (isDataTypeOrReduceTypeSpecial) {
697	        HCCL_INFO("[AllReduceAutoSelector][SelectDPUAlgo] not support INT64, UINT64, FP64.");
698	        return SelectorStatus::NOT_MATCH;
699	    } else if (topoInfo->topoLevelNums > 1) {
700	        if ((topoInfo->deviceNumPerModule == 1) || (topoInfo->level0Topo == Level0Shape::MESH_1D)) {
701	            selectAlgName = "DpuAllReduceSequenceMeshNHR"; // 对应executor最后register的第二个参数
702	            HCCL_INFO("Using algo DpuAllReduceSequenceMeshNHR");
703	            return SelectorStatus::MATCH;
704	        } else if (topoInfo->level0Topo == Level0Shape::MESH_1D_CLOS) {
705	            if (!topoInfo->level0PcieMix) {
706	                selectAlgName = "AicpuAllReducePipeLineUBX";
707	                HCCL_INFO("Using algo AicpuAllReducePipeLineUBX");
708	                return SelectorStatus::MATCH;
709	            } else {
710	                selectAlgName = "DpuAllReduceSequenceMeshNHR";
711	                HCCL_INFO("Using algo DpuAllReduceSequenceMeshNHR");
712	                return SelectorStatus::MATCH;
713	            }
714	        } else {
715	            selectAlgName = "DpuAllReduceSequenceMeshNHR";
716	            HCCL_INFO("Using algo DpuAllReduceSequenceMeshNHR");
717	            return SelectorStatus::MATCH;
718	        }
719	    }
720	
721	    return SelectorStatus::NOT_MATCH;
722	}
723	
724	REGISTER_SELECTOR_BY_OPTYPE(HcclCMDType::HCCL_CMD_ALLREDUCE, 18, AllReduceAutoSelector);
725	} // namespace ops_hccl
